scwin.fn_RefreshForm = function(interval) {
    setInterval("fn_list();", interval);
};


/*익일영업일 가져옴*/
scwin.fn_getDate = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral&outputMessageId=ULDSTF41001_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.mktverif.date.select";
    dts_getDate.DataID = encodeURI(url);
    dts_getDate.reset();
};
scwin.fn_QryUrl_BasPrc_Comp = function(pApplNo, pFormCd) {
    var url = "";
    if (pFormCd == "70766") {
        //권리락
        url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral&outputMessageId=ISU_BAS_PRC_REVW_PROC_COMP_LIST" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.isubasprc.verif.basprc.comp." + pFormCd + "&{P}param01=" + pApplNo + "&{P}param02=" + dts_List_2.getCellData(1, 'BAS_PRC');
    } else if (pFormCd == "70768") {
        //권배락
        url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral&outputMessageId=ISU_BAS_PRC_REVW_PROC_COMP_LIST" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.isubasprc.verif.basprc.comp." + pFormCd + "&{P}param01=" + pApplNo + "&{P}param02=" + dts_List_2.getCellData(1, 'BAS_PRC');
    } else if (pFormCd == "70795") {
        //기준가격안내
        url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral&outputMessageId=ISU_BAS_PRC_REVW_PROC_COMP_LIST" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.isubasprc.verif.basprc.comp." + pFormCd + "&{P}param01=" + pApplNo + "&{P}param02=" + dts_List_2.getCellData(1, 'BAS_PRC');
    } else if (pFormCd == "70793") {
        //매매개시일 기준가 산정 등에 관한 안내
        url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral&outputMessageId=ISU_BAS_PRC_REVW_PROC_COMP_LIST" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.isubasprc.verif.basprc.comp." + pFormCd + "&{P}param01=" + pApplNo + "&{P}param02=" + dts_List_2.getCellData(1, 'VALU_PRC') + "&{P}param03=" + dts_List_2.getCellData(1, 'HGST_ORD_PRC') + "&{P}param04=" + dts_List_2.getCellData(1, 'LWST_ORD_PRC');
    } else if (pFormCd == "32101") {
        //코넥스권리락
        url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral&outputMessageId=ISU_BAS_PRC_REVW_PROC_COMP_LIST" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.isubasprc.verif.basprc.comp." + pFormCd + "&{P}param01=" + pApplNo + "&{P}param02=" + dts_List_2.getCellData(1, 'BAS_PRC');
    } else if (pFormCd == "32102") {
        //코넥스권배락
        url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral&outputMessageId=ISU_BAS_PRC_REVW_PROC_COMP_LIST" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.isubasprc.verif.basprc.comp." + pFormCd + "&{P}param01=" + pApplNo + "&{P}param02=" + dts_List_2.getCellData(1, 'BAS_PRC');
    } else if (pFormCd == "32103") {
        //코넥스기준가격안내
        url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral&outputMessageId=ISU_BAS_PRC_REVW_PROC_COMP_LIST" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.isubasprc.verif.basprc.comp." + pFormCd + "&{P}param01=" + pApplNo + "&{P}param02=" + dts_List_2.getCellData(1, 'BAS_PRC');
    } else if (pFormCd == "32108") {
        //코넥스 매매개시일 기준가 산정 등에 관한 안내
        url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral&outputMessageId=ISU_BAS_PRC_REVW_PROC_COMP_LIST" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.isubasprc.verif.basprc.comp." + pFormCd + "&{P}param01=" + pApplNo + "&{P}param02=" + dts_List_2.getCellData(1, 'VALU_PRC') + "&{P}param03=" + dts_List_2.getCellData(1, 'HGST_ORD_PRC') + "&{P}param04=" + dts_List_2.getCellData(1, 'LWST_ORD_PRC');
    }
    return url;
};
scwin.isAlreadSubmittedCheck = function() {
    var appl_no = dts_List_2.getCellData(1, 'APPL_NO');
    var url = "/MktVerifSystem.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&method=isAlreadSubmittedCheck&outputMessageId=IS_ALREAD_SUBMITTED_CHECK";
    url += "&APPL_NO=" + dts_List_2.getCellData(1, 'APPL_NO');
    dts_getDate.DataID = encodeURI(url);
    dts_getDate.reset();
    return dts_getDate.getCellData(1, 'SUBMITTED_YN');
};
scwin.fn_verify_ok = function() {
    var rOK = "N";
    var appl_no = dts_List_2.getCellData(1, 'APPL_NO');
    var form_cd = dts_List_2.getCellData(1, 'DISCLS_MAINDOC_FORM_CD');
    dts_getDate.DataID = encodeURI(scwin.fn_QryUrl_BasPrc_Comp(appl_no, form_cd));
    dts_getDate.reset();
    return dts_getDate.getCellData(1, 'BIGO');
};


/*시장조치 내용 불러오기*/
scwin.fn_verify_bas_prc = function() {
    // 1차 검토자가 다시 2차 검토를 할경우 체크
    if (dts_List_2.getCellData(1, 'FST_REVWR_EMP_NO') == js_id) {
        $c.win.alert("1차 검토자와 2차 검토자는 같은 종목을 검토할수 없습니다.");
        return;
    }
    var isAlreadSubmitted = scwin.isAlreadSubmittedCheck();
    if (isAlreadSubmitted == "N") {
        var res = window.confirm("기준[평가] 가격을 검토하시겠습니까?");
        if (res) {
            var retOK = scwin.fn_verify_ok();
            if (retOK == "Y") {
                $c.win.alert("기준[평가] 가격 일치");
                // 1차 검토 일치인 경우
                if (dts_List_2.getCellData(1, 'FST_REVWR_EMP_NM') == '') {
                    var url = "/MktVerifSystem.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&method=saveBasPrcVerify";
                    url += "&USR_ID=" + js_id;
                    url += "&APPL_NO=" + dts_List_2.getCellData(1, 'APPL_NO');
                    url += "&VERIFY_NUM=1";
                    dts_parameter.DataID = encodeURI(url);
                    dts_parameter.reset();
                } else
                // 2차 검토 일치인 경우  

                {
                    var url = "/MktVerifSystem.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&method=saveBasPrcVerify";
                    url += "&USR_ID=" + js_id;
                    url += "&APPL_NO=" + dts_List_2.getCellData(1, 'APPL_NO');
                    url += "&VERIFY_NUM=2";
                    dts_parameter.DataID = encodeURI(url);
                    dts_parameter.reset();
                }
            } else {
                $c.win.alert("기준[평가] 가격 불일치");
            }
        }
    } else {
        $c.win.alert('해당 공시는 이미 처리되었습니다.');
    }
    scwin.fn_list();
};


/*기준평가가격 삭제*/
scwin.fn_delete_bas_prc = function() {
    var res = window.confirm("기준[평가] 가격을 삭제하시겠습니까?");
    if (res) {
        var url = "/MktVerifSystem.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04 + "&method=saveBasPrcVerify";
        url += "&USR_ID=" + js_id;
        url += "&APPL_NO=" + dts_List_2.getCellData(1, 'APPL_NO');
        url += "&VERIFY_NUM=3";
        dts_parameter.DataID = encodeURI(url);
        dts_parameter.reset();
    }
    scwin.fn_list();
};
scwin.fn_read_sync_cnt = function(pBzNm, pQryIdCnt) {
    dts_Cnt.DataID = encodeURI(scwin.fn_QryUrl_BasPrc_Comp(pBzNm, pQryIdCnt));
    dts_Cnt.reset();
    return dts_Cnt.getTotalRow();
};
scwin.fn_gridAddRow = function(pQryIdCnt, pQryId, pBzNm, gCnt) {
    dts_List_1.insertRow();
    dts_List_1.setCellData(dts_List_1.getTotalRow(), "QRY_ID_CNT", pQryIdCnt);
    dts_List_1.setCellData(dts_List_1.getTotalRow(), "QRY_ID", pQryId);
    dts_List_1.setCellData(dts_List_1.getTotalRow(), "BZ_NM", pBzNm);
    dts_List_1.setCellData(dts_List_1.getTotalRow(), "CNT_LDS", dts_Cnt.getCellData(1, "CNT_LDS"));
    dts_List_1.setCellData(dts_List_1.getTotalRow(), "CNT_MKT", dts_Cnt.getCellData(1, "CNT_MKT"));
    dts_List_1.setCellData(dts_List_1.getTotalRow(), "CNT_BIGYO", dts_Cnt.getCellData(1, "CNT_BIGYO"));
};
scwin.fn_QryUrl_Info = function(row, pApplNo, pFormCd) {
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=ISU_BAS_PRC_REVW_PROC_COMP_LIST" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.isubasprc.verif.basprc.select" + "&{P}param01=" + pApplNo;

    // if ( pFormCd = "" )  따른 처리가 생길경우 기술

    return url;
};
scwin.fn_allCheck_3 = function() {
    var checkArray = [chb_bzstat_20, chb_bzstat_22];
    if (chb_bzstat_99.checked == true) {
        for (var i = 0; i < checkArray.length; i++) {
            checkArray[i].setValue(1);
        }
    }
    if (chb_bzstat_99.checked == false) {
        for (var i = 0; i < checkArray.length; i++) {
            checkArray[i].setValue(0);
        }
    }
};
scwin.fn_read_sync_info = function(row, colid) {
    dts_List_2.DataID = encodeURI(scwin.fn_QryUrl_Info(row, dts_List_1.getCellData(row, 'APPL_NO'), dts_List_1.getCellData(row, 'DISCLS_MAINDOC_FORM_CD')));
    dts_List_2.reset();
    $c.cm.ShowWin(grd_List_2);
};
scwin.fn_getCondValue = function(pCnt, pVal, vCode) {
    if (pCnt > 0) {
        pVal += "," + vCode + "";
    } else {
        pVal = vCode;
    }
    return pVal;
};
scwin.fn_getCondition_3 = function() {
    var vStatCnt = 0;
    var vStatCond = '';
    if (chb_bzstat_99.checked == true) {
        vStatCond = '';
        vStatCnt++;
    } else {
        if (chb_bzstat_20.checked == true) {
            vStatCond = scwin.fn_getCondValue(vStatCnt, vStatCond, 'N');
            vStatCnt++;
        }
        if (chb_bzstat_22.checked == true) {
            vStatCond = scwin.fn_getCondValue(vStatCnt, vStatCond, 'Y');
            vStatCnt++;
        }
    }
    return vStatCond;
};


//시장조치 기준가검증 List
scwin.fn_list = function() {
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        dts_List_1.removeAll();
        var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral&outputMessageId=ISU_BAS_PRC_REVW_MI_PROC_LIST" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.isubasprc.verif.miproc.select" + "&{P}param01=" + scwin.mktId + "&{P}param02=" + scwin.mktId;
        dts_List_1.DataID = encodeURI(url);
        dts_List_1.reset();

        //		ShowWin(dts_List_1);	
        $c.cm.ShowWin(grd_List_1);
        dts_List_2.removeAll();
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral&outputMessageId=ISU_BAS_PRC_REVW_PROC_STAT_LIST" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.isubasprc.verif.procstat.select" + "&{P}param01=" + $c.stf.getObjectValue(txb_ISUR_CD_3) + "&{P}param02=" + $c.stf.getObjectValue(txb_ISUR_CD_3) + "&{P}param03=" + $c.stf.getObjectValue(edt_BzSDate) + "&{P}param04=" + $c.stf.getObjectValue(edt_BzEDate) + "&{P}param05=" + scwin.fn_getCondition_3() + "&{P}param06=" + scwin.fn_getCondition_3() + "&{P}param07=" + scwin.mktId + "&{P}param08=" + scwin.mktId;
        dts_ListBond.DataID = encodeURI(url);
        dts_ListBond.reset();
        $c.cm.ShowWin(grd_ListBond);
    }
};




/*시장정보수신된 내용이 있는지 체크*/
scwin.fn_btncnt = function() {
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=MKTVERIFSYS_CNT_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.mktverif.rdsrcvmktact.cnt.condition" + "&{P}param01=" + $c.stf.getObjectValue(edt_SDate);
    dts_btnCnt.DataID = encodeURI(url);
    dts_btnCnt.reset();
};



